  /* ---------- 站点：21 个朝代都有事件，一站一个事件，不再有时期站 ---------- */
  var STATIONS = [];
  DYNASTIES.forEach(function (d) {
    var evs = eventsOf(d.id);
    if (evs.length) {
      evs.forEach(function (ev) { STATIONS.push({ type: 'event', dyn: d, ev: ev }); });
    } else {
      STATIONS.push({ type: 'era', dyn: d, era: eraById(d.era) });
    }
  });
  function firstStationOf(dynId) {
    for (var i = 0; i < STATIONS.length; i++) if (STATIONS[i].dyn.id === dynId) return i;
    return 0;
  }
  function stationIndexOf(dynId, evId) {
    for (var i = 0; i < STATIONS.length; i++) {
      var st = STATIONS[i];
      if (st.dyn.id !== dynId) continue;
      if (evId) { if (st.type === 'event' && st.ev.id === evId) return i; }
      else return i;
    }
    return -1;
  }
